/// spec class `ARPackage` — `ARPackage : CollectableElement`.
#[derive(Debug, Default)]
pub struct ARPackage {
    base: CollectableElement,
    elements: Vec<ElementRef>,
    ar_packages: Vec<ARPackageId>,
    reference_bases: Vec<ReferenceBaseId>,
}

impl ARPackage {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn base(&self) -> &CollectableElement {
        &self.base
    }

    pub fn base_mut(&mut self) -> &mut CollectableElement {
        &mut self.base
    }

    // — forwarded accessors (the py inheritance surface) —
    //
    // Chain: ARPackage → CollectableElement → Identifiable →
    // MultilanguageReferrable → Referrable → ARObject.

    pub fn get_checksum(&self) -> Option<&str> {
        self.base.base().base().base().base().get_checksum()
    }

    pub fn get_timestamp(&self) -> Option<&str> {
        self.base.base().base().base().base().get_timestamp()
    }

    pub fn set_checksum(&mut self, value: impl Into<String>) -> &mut Self {
        // four base_mut hops reach ARObject, mirroring get_checksum
        self.base
            .base_mut()
            .base_mut()
            .base_mut()
            .base_mut()
            .set_checksum(value);
        self
    }

    pub fn set_timestamp(&mut self, value: impl Into<String>) -> &mut Self {
        self.base
            .base_mut()
            .base_mut()
            .base_mut()
            .base_mut()
            .set_timestamp(value);
        self
    }

    pub fn get_parent(&self) -> Option<ElementRef> {
        self.base.base().base().base().get_parent()
    }

    pub fn set_parent(&mut self, parent: Option<ElementRef>) -> &mut Self {
        // self.base is CollectableElement; three hops reach Referrable.
        self.base
            .base_mut()
            .base_mut()
            .base_mut()
            .set_parent(parent);
        self
    }

    pub fn get_short_name(&self) -> Option<&str> {
        self.base.get_short_name()
    }

    pub fn set_short_name(&mut self, value: impl Into<String>) -> &mut Self {
        self.base.set_short_name(value);
        self
    }

    pub fn get_uuid(&self) -> Option<&str> {
        self.base.base().get_uuid()
    }

    pub fn set_uuid(&mut self, value: impl Into<String>) -> &mut Self {
        self.base.base_mut().set_uuid(value);
        self
    }

    pub fn get_category(&self) -> Option<&str> {
        self.base.base().get_category()
    }

    pub fn set_category(&mut self, value: impl Into<String>) -> &mut Self {
        self.base.base_mut().set_category(value);
        self
    }

    pub fn get_admin_data(&self) -> Option<AdminDataId> {
        self.base.base().get_admin_data()
    }

    pub fn set_admin_data(&mut self, admin_data: AdminDataId) -> &mut Self {
        self.base.base_mut().set_admin_data(admin_data);
        self
    }

    /// py `removeAdminData` (inherited from Identifiable)
    pub fn remove_admin_data(&mut self) -> &mut Self {
        self.base.base_mut().remove_admin_data();
        self
    }

    // — own fields —

    pub fn get_elements(&self) -> &[ElementRef] {
        &self.elements
    }

    // Called from Document's factories (Task 8); until then only tests use
    // them, which the lib build does not see.
    #[allow(dead_code)]
    pub(crate) fn push_element(&mut self, element: ElementRef) {
        self.elements.push(element);
    }

    pub fn get_ar_packages(&self) -> &[ARPackageId] {
        &self.ar_packages
    }

    #[allow(dead_code)]
    pub(crate) fn push_ar_package(&mut self, ar_package: ARPackageId) {
        self.ar_packages.push(ar_package);
    }

    pub fn get_reference_bases(&self) -> &[ReferenceBaseId] {
        &self.reference_bases
    }

    pub fn push_reference_base(&mut self, id: ReferenceBaseId) -> &mut Self {
        self.reference_bases.push(id);
        self
    }
}

/// spec class `ReferenceBase` — `ReferenceBase : ARObject`
/// This meta-class establishes a basis for relative references. Reference
/// bases are identified by the short Label which shall be unique in the
/// current package.
/// (py-armodel ARPackage.py:386; pinned because it sits beside the pinned
/// ARPackage. Ref-typed fields are RefTypeId arena links (code_guide §6) so
/// the generated keep-compares resolve through Document.ref_types. py's
/// `globalElements` holds `ReferrableSubtypesEnum` literals — kept as
/// `String` because py's enum `setValue` never validates and the byte
/// round-trip needs the text verbatim.)
#[derive(Debug, Default)]
pub struct ReferenceBase {
    base: ARObject,
    base_is_this_package: Option<bool>,
    global_elements: Vec<String>,
    global_in_package_refs: Vec<RefTypeId>,
    is_default: Option<bool>,
    is_global: Option<bool>,
    package_ref: Option<RefTypeId>,
    short_label: Option<String>,
}

impl ReferenceBase {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn base(&self) -> &ARObject {
        &self.base
    }

    pub fn base_mut(&mut self) -> &mut ARObject {
        &mut self.base
    }

    pub fn get_base_is_this_package(&self) -> Option<bool> {
        self.base_is_this_package
    }

    pub fn set_base_is_this_package(&mut self, value: bool) -> &mut Self {
        self.base_is_this_package = Some(value);
        self
    }

    pub fn get_global_elements(&self) -> &[String] {
        &self.global_elements
    }

    pub fn push_global_elements(&mut self, value: impl Into<String>) -> &mut Self {
        self.global_elements.push(value.into());
        self
    }

    pub fn get_global_in_package_refs(&self) -> &[RefTypeId] {
        &self.global_in_package_refs
    }

    pub fn push_global_in_package_ref(&mut self, value: RefTypeId) -> &mut Self {
        self.global_in_package_refs.push(value);
        self
    }

    pub fn get_is_default(&self) -> Option<bool> {
        self.is_default
    }

    pub fn set_is_default(&mut self, value: bool) -> &mut Self {
        self.is_default = Some(value);
        self
    }

    pub fn get_is_global(&self) -> Option<bool> {
        self.is_global
    }

    pub fn set_is_global(&mut self, value: bool) -> &mut Self {
        self.is_global = Some(value);
        self
    }

    pub fn get_package_ref(&self) -> Option<RefTypeId> {
        self.package_ref
    }

    pub fn set_package_ref(&mut self, value: RefTypeId) -> &mut Self {
        self.package_ref = Some(value);
        self
    }

    pub fn get_short_label(&self) -> Option<&str> {
        self.short_label.as_deref()
    }

    pub fn set_short_label(&mut self, value: impl Into<String>) -> &mut Self {
        self.short_label = Some(value.into());
        self
    }

    pub fn get_checksum(&self) -> Option<&str> {
        self.base.get_checksum()
    }

    pub fn set_checksum(&mut self, value: impl Into<String>) -> &mut Self {
        self.base.set_checksum(value);
        self
    }

    pub fn get_timestamp(&self) -> Option<&str> {
        self.base.get_timestamp()
    }

    pub fn set_timestamp(&mut self, value: impl Into<String>) -> &mut Self {
        self.base.set_timestamp(value);
        self
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use slotmap::SlotMap;

    #[test]
    fn ar_package_accessors() {
        let mut package = ARPackage::new();
        package
            .set_short_name("Pkg")
            .set_uuid("u-1")
            .set_category("STD");

        assert_eq!(package.get_short_name(), Some("Pkg"));
        assert_eq!(package.get_uuid(), Some("u-1"));
        assert_eq!(package.get_category(), Some("STD"));
        assert_eq!(package.get_checksum(), None);
        assert_eq!(package.get_timestamp(), None);
        assert!(package.get_parent().is_none());
        assert!(package.get_elements().is_empty());
        assert!(package.get_ar_packages().is_empty());
        assert!(package.get_reference_bases().is_empty());
    }

    #[test]
    fn ar_package_links_use_ids() {
        let mut arena: SlotMap<ARPackageId, ARPackage> = SlotMap::with_key();
        let parent_id = arena.insert(ARPackage::new());

        let mut child = ARPackage::new();
        child.set_parent(Some(ElementRef::ARPackage(parent_id)));

        // The push methods are what Document's factories call (Task 8);
        // exercise them at the struct level here.
        let mut package = ARPackage::new();
        package.push_ar_package(parent_id);
        package.push_element(ElementRef::ARPackage(parent_id));
        assert_eq!(package.get_ar_packages(), &[parent_id]);
        assert_eq!(package.get_elements(), &[ElementRef::ARPackage(parent_id)]);

        assert!(matches!(child.get_parent(), Some(ElementRef::ARPackage(id)) if id == parent_id));
    }
}
